CREATE OR REPLACE FUNCTION public.galaxy_autonomy_workbench_receipts_v1(wanted_endpoint text,wanted_task uuid)
 RETURNS TABLE(operation_id uuid,action text,target_type text,target_id text,state text,details jsonb) LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $receipts$
 SELECT c.operation_id,COALESCE(c.proposal->>'kind','workbench-action'),
 CASE c.proposal->'target'->>'kind'
 WHEN 'post' THEN 'content-post' WHEN 'reply' THEN 'content-reply' WHEN 'section' THEN 'content-section' WHEN 'account' THEN 'account'
 WHEN 'case' THEN 'community-report' WHEN 'public-case' THEN 'community-report' WHEN 'chat-report' THEN 'chat-report'
 WHEN 'chat-file' THEN 'file-chat' WHEN 'forum-file' THEN 'file-forum' WHEN 'message-plan' THEN 'messaging-plan'
 WHEN 'projects' THEN 'project' WHEN 'methods' THEN 'method' WHEN 'rule' THEN 'rule-key'
 WHEN 'file' THEN CASE c.proposal->'request'->>'targetKind' WHEN 'chat' THEN 'file-chat' WHEN 'forum' THEN 'file-forum' END
 WHEN 'search-configuration' THEN 'search-quality' WHEN 'recommendation-theme' THEN 'recommendation-policy'
 WHEN 'ai-work-prompt' THEN 'ai-work-account'
 WHEN 'tag-creation' THEN CASE WHEN (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,tagId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='content-tag-create' AND c.proposal#>>'{target,kind}'='tag-creation' AND c.proposal#>>'{target,id}' IS NULL) THEN 'content-tag' END
 WHEN 'content-tag' THEN CASE WHEN (c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND (c.state='unknown' OR (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,tagId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='content-tag-update' AND c.proposal#>>'{target,kind}'='content-tag' AND c.result#>>'{receipt,tagId}'=c.proposal#>>'{target,id}')) THEN 'content-tag' END
 WHEN 'file-cleanup-creation' THEN CASE WHEN (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,planId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='file-cleanup-plan-create' AND c.proposal#>>'{target,kind}'='file-cleanup-creation' AND c.proposal#>>'{target,id}' IS NULL) THEN 'file-cleanup-plan' END
 WHEN 'file-cleanup-plan' THEN CASE WHEN c.proposal->>'kind'='file-cleanup-plan-cancel' THEN CASE WHEN (c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND (c.state='unknown' OR (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,planId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='file-cleanup-plan-cancel' AND c.proposal#>>'{target,kind}'='file-cleanup-plan' AND c.result#>>'{receipt,planId}'=c.proposal#>>'{target,id}')) THEN 'file-cleanup-plan' END ELSE 'file-cleanup-plan' END
 WHEN 'public-content-batch' THEN NULL ELSE c.proposal->'target'->>'kind' END,
 CASE WHEN c.proposal->>'kind'='public-content-batch' THEN NULL WHEN c.proposal->>'kind'='content-tag-create' THEN CASE WHEN (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,tagId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='content-tag-create' AND c.proposal#>>'{target,kind}'='tag-creation' AND c.proposal#>>'{target,id}' IS NULL) THEN c.result#>>'{receipt,tagId}' END WHEN c.proposal->>'kind'='content-tag-update' THEN CASE WHEN (c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND (c.state='unknown' OR (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,tagId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='content-tag-update' AND c.proposal#>>'{target,kind}'='content-tag' AND c.result#>>'{receipt,tagId}'=c.proposal#>>'{target,id}')) THEN c.proposal#>>'{target,id}' END WHEN c.proposal->>'kind'='file-cleanup-plan-create' THEN CASE WHEN (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,planId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='file-cleanup-plan-create' AND c.proposal#>>'{target,kind}'='file-cleanup-creation' AND c.proposal#>>'{target,id}' IS NULL) THEN c.result#>>'{receipt,planId}' END WHEN c.proposal->>'kind'='file-cleanup-plan-cancel' THEN CASE WHEN (c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND (c.state='unknown' OR (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,planId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='file-cleanup-plan-cancel' AND c.proposal#>>'{target,kind}'='file-cleanup-plan' AND c.result#>>'{receipt,planId}'=c.proposal#>>'{target,id}')) THEN c.proposal#>>'{target,id}' END ELSE c.proposal->'target'->>'id' END,
 CASE WHEN c.proposal->>'kind' IN ('content-tag-create','content-tag-update') THEN CASE WHEN (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,tagId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='content-tag-create' AND c.proposal#>>'{target,kind}'='tag-creation' AND c.proposal#>>'{target,id}' IS NULL) OR (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,tagId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='content-tag-update' AND c.proposal#>>'{target,kind}'='content-tag' AND c.result#>>'{receipt,tagId}'=c.proposal#>>'{target,id}') THEN 'completed' ELSE 'unknown' END WHEN c.proposal->>'kind' IN ('file-cleanup-plan-create','file-cleanup-plan-cancel') THEN CASE WHEN (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,planId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='file-cleanup-plan-create' AND c.proposal#>>'{target,kind}'='file-cleanup-creation' AND c.proposal#>>'{target,id}' IS NULL) OR (((c.operator_id<>'' AND c.operator_id=v.operator_id AND c.operator_id=NULLIF(t.configuration#>>'{externalWorkbench,operatorId}','') AND c.domain=t.domain AND v.domain=t.domain AND v.ai_account_id=t.ai_account_id AND c.conversation_id::text=t.configuration#>>'{externalWorkbench,conversationId}' AND v.session_id::text=t.configuration#>>'{externalWorkbench,sessionId}') AND c.state='completed' AND c.result->>'state'='completed' AND c.result->>'operationId'=c.operation_id::text AND c.result#>>'{receipt,planId}' ~ '(?i)^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$') AND c.proposal->>'kind'='file-cleanup-plan-cancel' AND c.proposal#>>'{target,kind}'='file-cleanup-plan' AND c.result#>>'{receipt,planId}'=c.proposal#>>'{target,id}') THEN 'completed' ELSE 'unknown' END WHEN c.state='completed' AND c.result->'receipt' IS NOT NULL AND c.result->'receipt'<>'null'::jsonb THEN 'completed' ELSE 'unknown' END,
 CASE WHEN c.proposal->>'kind'='public-content-batch' AND jsonb_typeof(c.result#>'{receipt,counts}')='object' AND jsonb_typeof(c.result#>'{receipt,items}')='array'
 THEN jsonb_build_object('counts',jsonb_build_object('applied',c.result#>'{receipt,counts,applied}','rejected',c.result#>'{receipt,counts,rejected}'),
  'items',(SELECT jsonb_agg(jsonb_build_object('kind',i->>'kind','id',i->>'id','status',i->>'status','code',i->'code','revision',i->'revision')) FROM jsonb_array_elements(c.result#>'{receipt,items}') i)) ELSE NULL END
 FROM operations_agentos_conversation_cards_v1 c LEFT JOIN operations_agentos_conversations_v1 v ON v.endpoint=c.endpoint AND v.id=c.conversation_id JOIN operations_autonomy_tasks_v1 t ON t.endpoint=c.endpoint
 AND (t.id=c.turn_id OR EXISTS(SELECT 1 FROM operations_autonomy_workbench_runs_v1 r WHERE r.endpoint=t.endpoint AND r.task_id=t.id AND r.turn_operation_id=c.turn_id))
 WHERE t.endpoint=wanted_endpoint AND t.id=wanted_task AND c.state IN ('completed','unknown')
 $receipts$;
REVOKE ALL ON FUNCTION public.galaxy_autonomy_workbench_receipts_v1(text,uuid) FROM PUBLIC;
